/*
 * The original's data blocks (src/data/<block>.c) and where an original data address is in them: each block
 * keeps the original's layout, so the address's offset in its block is its offset in the object.
 * Generated by tools/gen_data.py.
 */
#ifndef BMX_DATA_BLOCKS_H
#define BMX_DATA_BLOCKS_H

#include <stdint.h>

extern const struct BmxRdata bmxRdata; /* the original's .rdata */
extern struct BmxData bmxData;         /* the original's .data, initialised part */
extern struct BmxBss bmxBss;           /* the original's .data, zero-initialised tail */
extern struct BmxImports bmxImports;   /* the original's .idata up to the end of its import slots */
extern struct BmxData1 bmxData1;       /* the original's .data1 */
extern struct BmxRwBss bmxRwBss;       /* the original's _rwdseg (RenderWare data) */
extern const struct BmxInputTables
    bmxInputTables; /* dinput.lib's object tables, which the linker put into the original's .text */

/* Never reached for a data address the code names (tools/gen_data.py checks them all). */
char *bmxDataBadAddress(uint32_t addr);

/* The block holding original data address addr, as a char pointer. */
#define BMX_DATA_AT(addr)                                                                                      \
    ((uint32_t)(addr) - 0x0054d000u < 0x3bd8u     ? (char *)&bmxRdata + ((uint32_t)(addr) - 0x0054d000u)       \
     : (uint32_t)(addr) - 0x00551000u < 0x19000u  ? (char *)&bmxData + ((uint32_t)(addr) - 0x00551000u)        \
     : (uint32_t)(addr) - 0x0056a000u < 0x12ef90u ? (char *)&bmxBss + ((uint32_t)(addr) - 0x0056a000u)         \
     : (uint32_t)(addr) - 0x00699000u < 0x87cu    ? (char *)&bmxImports + ((uint32_t)(addr) - 0x00699000u)     \
     : (uint32_t)(addr) - 0x0069b000u < 0x4086u   ? (char *)&bmxData1 + ((uint32_t)(addr) - 0x0069b000u)       \
     : (uint32_t)(addr) - 0x006a0000u < 0x109u    ? (char *)&bmxRwBss + ((uint32_t)(addr) - 0x006a0000u)       \
     : (uint32_t)(addr) - 0x004afc60u < 0x12c0u   ? (char *)&bmxInputTables + ((uint32_t)(addr) - 0x004afc60u) \
                                                  : bmxDataBadAddress((uint32_t)(addr)))

#endif
